import { Component, computed, inject, input, resource } from '@angular/core';
import { Title } from '@angular/platform-browser';
import { RouterLink } from '@angular/router';
import { BRAND } from '../../core/constants/brand.constants';
import { AdminApiService } from '../../core/services/admin-api.service';
import { TemplateCatalogService } from '../../core/services/template-catalog.service';
import { WeddingWebsite } from '../../website/wedding-website/wedding-website';

/** A couple's own website, generated by the admin: /i/<slug>. Full screen, no site chrome. */
@Component({
  selector: 'app-generated-site-page',
  imports: [RouterLink, WeddingWebsite],
  template: `
    @if (site.isLoading()) {
      <div class="state"><span class="spinner" aria-hidden="true"></span><p>Opening the invitation…</p></div>
    } @else if (template(); as t) {
      <app-wedding-website [template]="t" [details]="site.value()!.details" />
    } @else {
      <div class="state">
        <h1>Invitation not found</h1>
        <p>This link may be mistyped, or the invitation was removed.</p>
        <a class="btn btn-primary" routerLink="/">Visit {{ brand }}</a>
      </div>
    }
  `,
  styles: `
    :host { display: block; }
    .state { display: grid; justify-items: center; gap: 0.8rem; padding: 6rem 1.5rem; text-align: center; color: var(--muted); }
    .state h1 { margin: 0; color: var(--text); font-family: var(--font-display); }
    .spinner { width: 2.2rem; height: 2.2rem; border: 3px solid var(--line); border-top-color: var(--plum); border-radius: 50%; animation: spin 0.9s linear infinite; }
    @keyframes spin { to { rotate: 1turn; } }
  `,
})
export class GeneratedSitePage {
  readonly slug = input.required<string>();

  private readonly api = inject(AdminApiService);
  private readonly catalog = inject(TemplateCatalogService);
  private readonly title = inject(Title);
  protected readonly brand = BRAND.name;

  protected readonly site = resource({
    params: () => this.slug(),
    loader: ({ params }) => this.api.site(params),
  });

  protected readonly template = computed(() => {
    if (this.site.error() || !this.site.hasValue()) return undefined;
    const value = this.site.value();
    const design = this.catalog.bySlug(value.design);
    if (design?.kind !== 'website') return undefined;
    this.title.setTitle(`${value.details.bride} & ${value.details.groom} – Wedding Invitation`);
    return design;
  });
}
